-- Existing non-expert users are the pre-V2 client cohort. Assigning them to the
-- immutable legacy policy prevents a later control switch from reclassifying history.
INSERT INTO client_commercial_policy_assignments (user_id, policy_version, control_version)
SELECT u.id, 'legacy_package_v1', 1
FROM users u
WHERE NOT EXISTS (SELECT 1 FROM experts e WHERE e.user_id = u.id)
ON CONFLICT (user_id) DO NOTHING;
