ALTER TABLE expert_referral_admin_execution_results DROP CONSTRAINT expert_referral_admin_result_action_allowed, ADD CONSTRAINT expert_referral_admin_result_action_allowed CHECK (action in ('expert_referral.batch_generate','expert_referral.code_revoke','expert_referral.issuance_override','expert_referral.abuse_hold_open','expert_referral.abuse_hold_close','expert_residency.tariff_create','expert_residency.tariff_retire','expert_referral.hold_replay','expert_referral.feature_switch','client_commercial_policy.control_v2','expert_residency.tariff_create_v2'));
