ALTER TABLE expert_referral_admin_execution_results DROP CONSTRAINT expert_referral_admin_result_exact_schema, ADD CONSTRAINT expert_referral_admin_result_exact_schema CHECK ((action='expert_referral.code_revoke' AND safe_result ?& array['id','status'] AND safe_result - array['id','status']='{}'::jsonb AND safe_result->>'id'=object_id::text AND safe_result->>'status'='revoked') OR (action='expert_referral.issuance_override' AND safe_result ? 'overrideId' AND safe_result - 'overrideId'='{}'::jsonb AND safe_result->>'overrideId'=object_id::text) OR (action='expert_referral.feature_switch' AND safe_result ? 'version' AND safe_result - 'version'='{}'::jsonb AND jsonb_typeof(safe_result->'version')='number' AND (safe_result->>'version')::numeric=expected_version+1) OR (action='expert_referral.batch_generate' AND safe_result ?& array['batchId','count'] AND safe_result - array['batchId','count']='{}'::jsonb AND jsonb_typeof(safe_result->'batchId')='string' AND jsonb_typeof(safe_result->'count')='number') OR (action='expert_residency.tariff_create_v2' AND safe_result ? 'tariffVersionId' AND safe_result - 'tariffVersionId'='{}'::jsonb) OR (action='client_commercial_policy.control_v2' AND object_id='00000000-0000-0000-0000-000000000041'::uuid AND safe_result ?& array['version','admissionPolicy'] AND safe_result - array['version','admissionPolicy']='{}'::jsonb AND jsonb_typeof(safe_result->'version')='number' AND (safe_result->>'version')::numeric > 0 AND (safe_result->>'version')::numeric % 1 = 0 AND jsonb_typeof(safe_result->'admissionPolicy')='string' AND safe_result->>'admissionPolicy' in ('legacy_package_v1','free_client_v2')));
